12	// V2: Notifies the affiliate's configured inbox of a new enquiry submitted via the contact section block.
13	class SiteEnquiryNotification extends Mailable
14	{
15	    use Queueable, SerializesModels;
16	
17	    public function __construct(
18	        public readonly Enquiry $enquiry,
19	    ) {}
20	
21	    public function envelope(): Envelope
22	    {
23	        return new Envelope(
24	            subject: "New enquiry from {$this->enquiry->name} — {$this->enquiry->subject}",
25	        );
26	    }
27	
28	    public function content(): Content
29	    {
30	        $dashboardUrl = rtrim((string) config('app.dashboard_url', config('app.url')), '/').'/enquiries';
31	
32	        return new Content(
33	            view: 'emails.enquiry-notification',
34	            with: [
35	                'enquiry' => $this->enquiry,
36	                'dashboardUrl' => $dashboardUrl,
37	            ],
38	        );
39	    }
40	}
